// Vector001: fixed-point 3D vector arithmetic: sums, cross products and dot products of random vectors.
// Generated by `dotnet run --project Runner -c Release -- generate`; change the generator, not this file.
#include "group0/vector001.h"

#include "common.h"

namespace group0::vector001 {

Vec3 Vec3::add(const Vec3& other) const {
    return {x + other.x, y + other.y, z + other.z};
}

Vec3 Vec3::scale(uint64_t factor) const {
    return {x * factor, y * factor, z * factor};
}

uint64_t Vec3::dot(const Vec3& other) const {
    return x * other.x + y * other.y + z * other.z;
}

Vec3 Vec3::cross(const Vec3& other) const {
    return {y * other.z - z * other.y, z * other.x - x * other.z, x * other.y - y * other.x};
}

namespace {

uint64_t simulate(uint64_t seed) {
    common::Rng rng(seed);
    Vec3 sum;
    for (int i = 0; i < 22; ++i) {
        const uint64_t x = rng.next();
        const uint64_t y = rng.next();
        const uint64_t z = rng.next();
        const Vec3 v{x, y, z};
        const Vec3 w = v.cross(sum).add(v.scale(0x46FC33FF15BEF56BULL));
        sum = sum.add(w);
        if ((sum.dot(v) & 1) == 1) {
            sum = sum.scale(0xDD4AAB4072C7E9ULL);
        }
    }
    return sum.dot(sum) ^ sum.x;
}

uint64_t kernelA(uint64_t x, uint64_t y) {
    uint64_t a = x & (y << 6);
    uint64_t b = y >> 47;
    for (uint64_t i = 0; i < 6; ++i) {
        a = (a + i) * (i ^ b);
        b = b * common::rotl(i << 49, 12);
        if (((a - 156ULL) & 1023ULL) != 523ULL) {
            a = a | ((b | 0x3376D34B666D4591ULL) % 728ULL);
        } else {
            b = (b * a) + (b ^ 154ULL);
        }
    }
    if (((b * x) & 1023ULL) == 529ULL) {
        a = a & ((b - 88ULL) >> 26);
    } else {
        b = b | (a + x);
    }
    const uint64_t c = x + (b * 55ULL);
    return c ^ (a + b);
}

uint64_t kernelB(uint64_t x, uint64_t y) {
    uint64_t a = common::rotl(x, 27);
    uint64_t b = y & 255ULL;
    for (uint64_t i = 0; i < 6; ++i) {
        a = a - ((b + x) + (b & 118ULL));
        b = common::rotl(b, 18) - (b << 21);
        if (((i ^ b) & 65535ULL) > 34281ULL) {
            a = a - ((i >> 55) + 0xA01421F728036A41ULL);
        } else {
            b = common::rotl(b * 158ULL, 12);
        }
    }
    const uint64_t c = common::rotl(a, 16) << 8;
    const uint64_t d = (b << 1) & (a ^ 40ULL);
    return (c ^ (a ^ b)) + d;
}

}  // namespace

uint64_t mix(uint64_t x) {
    return kernelB(kernelA(x, 0x339596C5AC4F1FB1ULL), x ^ 0x3A486CEBCEFA48B7ULL);
}

uint64_t run(uint64_t seed) {
    uint64_t r = simulate(seed ^ 0xD0F1527C73B2EFBDULL);
    return mix(r);
}

}  // namespace group0::vector001
